const CasinoSprite kCasinoSprites[] = {
    {"seven", 16, 16, kCasino_seven, sizeof(kCasino_seven)},
    {"cherry", 16, 16, kCasino_cherry, sizeof(kCasino_cherry)},
    {"coin", 16, 16, kCasino_coin, sizeof(kCasino_coin)},
    {"bell", 16, 16, kCasino_bell, sizeof(kCasino_bell)},
    {"star", 16, 16, kCasino_star, sizeof(kCasino_star)},
    {"cup", 16, 16, kCasino_cup, sizeof(kCasino_cup)},
};
const int kCasinoSpriteCount = static_cast<int>(sizeof(kCasinoSprites) / sizeof(kCasinoSprites[0]));

const CasinoSprite* find_casino_sprite(std::string_view id) {
  for (int i = 0; i < kCasinoSpriteCount; ++i) {
    if (id == kCasinoSprites[i].id) {
      return &kCasinoSprites[i];
    }
  }
  return nullptr;
}

